en:{save:'Save draft',review:'Request approval',approved:'Approved process map',draft:'Draft: running business rules stay unchanged',process:'Process',stage:'Add stage',decision:'Add condition',connect:'Connect selected → next',title:'Stage title',role:'Role',person:'Assignee',condition:'Condition / parameters',remove:'Remove selected stage',history:'Version history',restore:'Restore as a new draft',open:'Open revision',export:'Export draw.io',svg:'Export SVG',import:'Import draw.io',error:'Action failed',saved:'Saved. Running business rules are unchanged.',conflict:'Another tab changed the draft. Open its current revision.',select:'Select a block',zoom:'Zoom',reset:'Fit diagram',help:'Drag a block or use arrow keys. To link blocks, select one, press Connect and select its target. Saving and rollback only create drafts; activation requires separate Owner approval and QA.'},
