const locale=()=>/^zh/i.test(document.documentElement.lang)?'zh':/^en/i.test(document.documentElement.lang)?'en':'ru';
const node=(tag,text,attrs={})=>{const e=document.createElement(tag);if(text!==null)e.textContent=text;for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;};
const svgNode=(tag,attrs={})=>{const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;};
let approved=null,baseHash=null,model=null,head=null,revisions=[],processId='P01',selected=null,connecting=false,scale=1,pan={x:0,y:0},busy=false,host=null,svg=null,inspector=null,drag=null,dirty=false;
const process=()=>model.processes.find(x=>x.id===processId);
function materialize(p){if(!p.edges)p.edges=processEdges(p).map(e=>({from:p.nodes[e.from].id,to:p.nodes[e.to].id,condition:e.label||''}));for(const[i,n]of p.nodes.entries())n.position??={x:60+Object.keys(model.roles).indexOf(n.role)*260,y:70+i*130};}
function message(text,error=false){const p=host?.querySelector('.ow-editor-message');if(p){p.textContent=text;p.setAttribute('role',error?'alert':'status');}}
async function api(path,body){const r=await fetch('/api/process-models'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(r.status===409?L[locale()].conflict:(data.error||'HTTP '+r.status));return data;}
function download(name,body,type){const a=node('a',null),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function drawio(){
 const doc=document.implementation.createDocument('','mxfile'),diagram=doc.createElement('diagram');diagram.setAttribute('name',model.version);const mx=doc.createElement('mxGraphModel'),root=doc.createElement('root');
 const cell=(id,parent)=>{const c=doc.createElement('mxCell');c.setAttribute('id',id);if(parent)c.setAttribute('parent',parent);root.append(c);return c;};cell('0');cell('1','0');
 const state=doc.createElement('UserObject');state.setAttribute('id','portal-model');state.setAttribute('portalModel',JSON.stringify(model));root.append(state);
 for(const p of model.processes){materialize(p);for(const n of p.nodes){const c=cell(n.id,'1');c.setAttribute('vertex','1');c.setAttribute('value',n.title);c.setAttribute('portalProcess',p.id);c.setAttribute('portalRole',n.role);c.setAttribute('style',n.type==='condition'?'rhombus;whiteSpace=wrap;':'rounded=1;whiteSpace=wrap;');const g=doc.createElement('mxGeometry');for(const[k,v]of Object.entries({x:n.position.x,y:n.position.y,width:220,height:82,as:'geometry'}))g.setAttribute(k,String(v));c.append(g);}for(const[i,e]of p.edges.entries()){const c=cell(p.id+'-edge-'+i,'1');c.setAttribute('edge','1');c.setAttribute('source',e.from);c.setAttribute('target',e.to);c.setAttribute('value',e.condition||'');const g=doc.createElement('mxGeometry');g.setAttribute('relative','1');g.setAttribute('as','geometry');c.append(g);}}
 mx.append(root);diagram.append(mx);doc.documentElement.append(diagram);return new XMLSerializer().serializeToString(doc);
}
function importModel(text){
 if(text.length>2*1024*1024)throw Error('File too large');const doc=new DOMParser().parseFromString(text,'text/xml');if(doc.querySelector('parsererror'))throw Error('Invalid draw.io XML');
 const embedded=doc.querySelector('UserObject[portalModel]');const candidate=embedded?JSON.parse(embedded.getAttribute('portalModel')):structuredClone(approved);
 if(candidate.version!==approved.version||candidate.processes.length!==10)throw Error('Preserve P01–P10');
 for(const p of candidate.processes){if(!approved.processes.some(x=>x.id===p.id))throw Error('Unknown process');for(const n of p.nodes){const c=doc.getElementById(n.id)||[...doc.querySelectorAll('mxCell')].find(x=>x.getAttribute('id')===n.id);const g=c?.querySelector('mxGeometry');if(c){n.title=c.getAttribute('value')||n.title;n.role=c.getAttribute('portalRole')||n.role;if(g)n.position={x:Number(g.getAttribute('x')),y:Number(g.getAttribute('y'))};}if(!Object.hasOwn(approved.roles,n.role))throw Error('Unknown role');}}
 for(const p of candidate.processes){const ids=new Set(p.nodes.map(n=>n.id));p.edges=[...doc.querySelectorAll('mxCell[edge="1"]')].filter(c=>ids.has(c.getAttribute('source'))&&ids.has(c.getAttribute('target'))).map(c=>({from:c.getAttribute('source'),to:c.getAttribute('target'),condition:c.getAttribute('value')||''}));} model=candidate;selected=null;dirty=true;draw();inspect();
}
function draw(){
 if(!svg||!model)return;const p=process();materialize(p);svg.replaceChildren();svg.setAttribute('viewBox',`${pan.x} ${pan.y} ${1200/scale} ${850/scale}`);
 const defs=svgNode('defs'),marker=svgNode('marker',{id:'ow-arrow',viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:7,markerHeight:7,orient:'auto-start-reverse'});marker.append(svgNode('path',{d:'M 0 0 L 10 5 L 0 10 z',fill:'#496b89'}));defs.append(marker);svg.append(defs);
 for(const[i,r]of Object.keys(model.roles).entries()){svg.append(svgNode('rect',{x:i*260,y:0,width:260,height:2500,fill:i%2?'#e4edf5':'#f2f6fa',stroke:'#bdcdd9'}));const t=svgNode('text',{x:i*260+12,y:28});t.textContent=model.roles[r];svg.append(t);}
 for(const e of p.edges){const a=p.nodes.find(n=>n.id===e.from),b=p.nodes.find(n=>n.id===e.to);if(!a||!b)continue;svg.append(svgNode('path',{d:`M${a.position.x+110} ${a.position.y+82} L${b.position.x+110} ${b.position.y}`,stroke:'#496b89','stroke-width':2,fill:'none','marker-end':'url(#ow-arrow)'}));if(e.condition){const t=svgNode('text',{x:(a.position.x+b.position.x)/2+115,y:(a.position.y+b.position.y)/2+38});t.textContent=e.condition.slice(0,38);svg.append(t);}}
 for(const n of p.nodes){const g=svgNode('g',{'data-editor-node':n.id,tabindex:'0',role:'button','aria-label':n.title,transform:`translate(${n.position.x},${n.position.y})`});g.append(svgNode('rect',{width:220,height:82,rx:n.type==='condition'?30:9,fill:n.id===selected?'#d4ebdf':'#fff',stroke:n.id===selected?'#176b53':'#718da3','stroke-width':n.id===selected?3:1.5}));const title=svgNode('text',{x:12,y:24});for(const [i,line]of (n.title.match(/.{1,27}/gu)||[]).slice(0,2).entries()){const t=svgNode('tspan',{x:12,dy:i?18:0});t.textContent=line;title.append(t);}const role=svgNode('text',{x:12,y:70});role.textContent=model.roles[n.role];g.append(title,role);svg.append(g);}
}
function inspect(){
 if(!inspector)return;const w=L[locale()],p=process(),n=p.nodes.find(x=>x.id===selected);inspector.replaceChildren(node('h3',n?n.id:w.select));if(!n)return;
 function field(label,key,tag='input'){const wrap=node('label',label),f=node(tag,null,{name:'editor-'+key});f.value=n[key]||'';f.oninput=()=>{n[key]=f.value;dirty=true;if(key==='title')draw();};wrap.append(f,node('small',label+' · '+n.id));inspector.append(wrap);return f;}
 field(w.title,'title').required=true;const label=node('label',w.role),roles=node('select',null,{name:'editor-role'});for(const[r,t]of Object.entries(model.roles))roles.append(node('option',t,{value:r}));roles.value=n.role;roles.onchange=()=>{n.role=roles.value;dirty=true;draw();};label.append(roles);inspector.append(label);field(w.person,'assignee');field(w.condition,'detail','textarea');
 for(const e of p.edges.filter(e=>e.from===selected)){const l=node('label',`${e.from} → ${e.to}`),f=node('input',null,{'data-editor-edge':e.to});f.value=e.condition;f.oninput=()=>{e.condition=f.value;dirty=true;draw();};l.append(f);inspector.append(l);}
 const remove=node('button',w.remove,{type:'button'});remove.onclick=()=>{if(p.nodes.length<=1)return;p.nodes=p.nodes.filter(x=>x.id!==selected);p.edges=p.edges.filter(x=>x.from!==selected&&x.to!==selected);selected=null;dirty=true;draw();inspect();};inspector.append(remove);
}
async function save(action='save',revisionId){
 if(busy)return;busy=true;host.querySelectorAll('button[data-mutates]').forEach(b=>b.disabled=true);
 try{const data=await api('',{action,model,revisionId,baseHash,expectedHead:head,requestId:crypto.randomUUID()});head=data.revision.model_sha256;if(action==='restore'){model=(await api('?id='+data.revision.id)).revision.model;selected=null;draw();inspect();}dirty=false;message(L[locale()].saved);await history();}
 catch(e){message(e.message,true);}finally{busy=false;host.querySelectorAll('button[data-mutates]').forEach(b=>b.disabled=false);}
}
async function history(offset=0,append=false){const data=await api(offset?'?offset='+offset:'');approved=data.approvedModel;baseHash=data.approvedHash;revisions=append?[...revisions,...data.revisions]:data.revisions;if(!model)head=revisions[0]?.model_sha256||null;const list=host.querySelector('.ow-editor-revisions');if(!list)return;list.replaceChildren();for(const r of revisions){const wrap=node('div',null,{class:'ow-record'}),w=L[locale()];wrap.append(node('small',`${new Date(r.created_at).toLocaleString('ru-RU',{timeZone:'Europe/Minsk'})} · ${r.created_by} · ${r.status}`));const open=node('button',w.open,{type:'button'}),restore=node('button',w.restore,{type:'button','data-mutates':''});open.onclick=async()=>{try{const data=await api('?id='+r.id);model=data.revision.model;selected=null;dirty=false;draw();inspect();}catch(e){message(e.message,true);}};restore.onclick=()=>save('restore',r.id);wrap.append(open,restore);list.append(wrap);}if(data.nextOffset!==null){const more=node('button','…',{type:'button'});more.onclick=()=>history(data.nextOffset,true);list.append(more);}}
async function mount(){
 const target=document.querySelector('.cabinet-app[data-cabinet-role="owner"] #ow-process-editor');if(!target||target===host)return;host=target;const w=L[locale()];host.replaceChildren(node('p',w.draft),node('p',w.help));
 const toolbar=node('div',null,{class:'ow-toolbar'}),choice=node('select',null,{'aria-label':w.process});toolbar.append(choice);
 const button=(text,fn,mutates=false)=>{const b=node('button',text,{type:'button',...(mutates?{'data-mutates':''}:{})});b.onclick=fn;toolbar.append(b);return b;};
 button(w.save,()=>save(),true);button(w.review,()=>save('request_review'),true);button(w.connect,()=>{connecting=true;});button('−',()=>{scale=Math.max(.3,scale-.2);draw();});button('+',()=>{scale=Math.min(3,scale+.2);draw();});button(w.reset,()=>{scale=.6;pan={x:0,y:0};draw();});
 button(w.export,()=>download('business-process-draft.drawio',drawio(),'application/xml'));button(w.svg,()=>download(processId+'-draft.svg',new XMLSerializer().serializeToString(svg),'image/svg+xml'));
 const upload=node('input',null,{type:'file',accept:'.drawio,.xml','aria-label':w.import});upload.onchange=async()=>{try{if(upload.files[0])importModel(await upload.files[0].text());}catch(e){message(e.message,true);}};toolbar.append(upload);const permanent=node('a',w.approved,{href:'./process-map.html',target:'_blank',rel:'noopener'});toolbar.append(permanent);host.append(toolbar);
 const grid=node('div',null,{class:'ow-editor-grid'}),palette=node('div',null,{class:'ow-editor-palette'}),canvas=node('div',null,{class:'ow-editor-canvas'});svg=svgNode('svg',{role:'group','aria-label':w.process});canvas.append(svg);inspector=node('aside',null,{class:'ow-editor-inspector'});grid.append(palette,canvas,inspector);host.append(grid,node('p','',{class:'ow-editor-message',role:'status'}),node('h3',w.history),node('div',null,{class:'ow-editor-revisions'}));
 for(const type of ['stage','condition']){const b=node('button',type==='stage'?w.stage:w.decision,{type:'button'});b.onclick=()=>{const p=process(),id=p.id+'-'+crypto.randomUUID().slice(0,8);p.nodes.push({id,type,title:type==='stage'?w.stage:w.decision,role:'owner',status:'draft',detail:'',position:{x:80,y:80+p.nodes.length*120}});selected=id;dirty=true;draw();inspect();};palette.append(b);}
 try{await history();model??=structuredClone(approved);for(const p of model.processes)choice.append(node('option',p.id+' · '+p.title,{value:p.id}));choice.value=processId;choice.onchange=()=>{processId=choice.value;selected=null;draw();inspect();};draw();inspect();}catch(e){message(w.error+': '+e.message,true);}
 svg.addEventListener('pointerdown',e=>{const g=e.target.closest('[data-editor-node]');if(g){const id=g.getAttribute('data-editor-node');if(connecting&&selected){if(!process().edges.some(e=>e.from===selected&&e.to===id))process().edges.push({from:selected,to:id,condition:''});connecting=false;dirty=true;}selected=id;const n=process().nodes.find(x=>x.id===id);drag={id,x:e.clientX,y:e.clientY,start:{...n.position}};draw();inspect();}else drag={pan:true,x:e.clientX,y:e.clientY,start:{...pan}};e.preventDefault();});
 svg.addEventListener('keydown',e=>{const g=e.target.closest('[data-editor-node]');if(!g)return;const n=process().nodes.find(n=>n.id===g.getAttribute('data-editor-node'));if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();n.position.x+=e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0;n.position.y+=e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0;selected=n.id;dirty=true;draw();svg.querySelector('[data-editor-node="'+n.id+'"]')?.focus();}else if(e.key==='Enter'){selected=n.id;inspect();}});
}
window.addEventListener('pointermove',e=>{if(!drag||!svg?.isConnected)return;const factor=(1200/scale)/svg.getBoundingClientRect().width;if(drag.pan){pan.x=drag.start.x-(e.clientX-drag.x)*factor;pan.y=drag.start.y-(e.clientY-drag.y)*factor;}else{const n=process().nodes.find(x=>x.id===drag.id);n.position={x:drag.start.x+(e.clientX-drag.x)*factor,y:drag.start.y+(e.clientY-drag.y)*factor};dirty=true;}draw();});window.addEventListener('pointerup',()=>drag=null);
window.addEventListener('ow-process-editor-open',()=>void mount());new MutationObserver(()=>{if(!host?.isConnected)void mount();}).observe(document.getElementById('root')||document.body,{childList:true,subtree:true});void mount();
window.addEventListener('beforeunload',e=>{if(dirty&&host?.isConnected){e.preventDefault();e.returnValue='';}});
